import{_ as t,o,c as r,a2 as a}from"./chunks/framework.CpZKh-tG.js";const p=JSON.parse('{"title":"Science Cover Style Bible","description":"","frontmatter":{},"headers":[],"relativePath":"science-cover-style-bible.md","filePath":"science-cover-style-bible.md"}'),s={name:"science-cover-style-bible.md"};function n(i,e,c,d,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="science-cover-style-bible" tabindex="-1">Science Cover Style Bible <a class="header-anchor" href="#science-cover-style-bible" aria-label="Permalink to &quot;Science Cover Style Bible&quot;">​</a></h1><p><em>The visual language for /science chapter covers + the /science landing hero.</em><em>v1 · 2026-06-23 · grounded in the five &quot;loved&quot; covers: scales-time, planets, orbits, transfers, porkchop.</em></p><hr><h2 id="_0-why-this-exists" tabindex="-1">0. Why this exists <a class="header-anchor" href="#_0-why-this-exists" aria-label="Permalink to &quot;0. Why this exists&quot;">​</a></h2><p>The first chapter covers (scales-time, planets, orbits, transfers, porkchop) share one coherent DNA — <strong>celestial-poetic</strong>. Later covers (history, propulsion, space-stations, life-in-space, observation, mission-phases) drifted into a second register — <strong>technical-schematic</strong> (icons, wireframe boxes, bar charts, monospace labels). The set lost coherence because no spec was written down. This is that spec. Every new or re-done cover — and any Higgsfield-generated art — must clear this bar so the family stays whole.</p><p><strong>The rule of thumb:</strong> a cover paints <em>the sky</em>, not <em>the hardware</em>. Mood over mechanism. The diagrams (per-page) carry the mechanism; the covers set the mood.</p><hr><h2 id="_1-the-two-registers-—-and-which-one-wins" tabindex="-1">1. The two registers — and which one wins <a class="header-anchor" href="#_1-the-two-registers-—-and-which-one-wins" aria-label="Permalink to &quot;1. The two registers — and which one wins&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th><strong>Celestial-poetic</strong> (KEEP)</th><th><strong>Technical-schematic</strong> (AVOID on covers)</th></tr></thead><tbody><tr><td>Subject</td><td>orbits, sun, planets, trajectory arcs — the sky</td><td>rockets, station boxes, timelines, bar charts</td></tr><tr><td>Type</td><td>italic serif whisper-caption</td><td>monospace UPPERCASE labels</td></tr><tr><td>Feeling</td><td>atmospheric, restrained, art</td><td>engineering UI, schematic</td></tr><tr><td>Examples</td><td>scales-time, planets, orbits, transfers, porkchop</td><td>history, propulsion, space-stations, life-in-space, observation, mission-phases</td></tr></tbody></table><p>Covers are <strong>celestial-poetic, always.</strong> If a chapter&#39;s subject is inherently hardware (propulsion, space-stations), express it <em>celestially</em> — a thrust arc and a receding trajectory, not a rocket icon; an orbital ring with a single bright node, not a wireframe truss.</p><hr><h2 id="_2-palette-—-exact-tokens" tabindex="-1">2. Palette — exact tokens <a class="header-anchor" href="#_2-palette-—-exact-tokens" aria-label="Permalink to &quot;2. Palette — exact tokens&quot;">​</a></h2><p>The app field behind every cover is <strong><code>#04040c</code></strong> (deep near-black navy). Covers are drawn transparent over it. Generated raster art must use <code>#04040c</code> as the base field.</p><table tabindex="0"><thead><tr><th>Role</th><th>Value</th><th>Use</th></tr></thead><tbody><tr><td><strong>Field</strong></td><td><code>#04040c</code></td><td>background, always</td></tr><tr><td><strong>Accent (cyan)</strong></td><td><code>#4ecdc4</code></td><td>the ONE hero line — a trajectory, the live orbit, the focal arc. Used sparingly.</td></tr><tr><td><strong>Sun / gold</strong></td><td><code>#ffc850</code></td><td>the star; warm focal glow</td></tr><tr><td><strong>Earth blue</strong></td><td><code>#4b9cd3</code> (<code>rgba(75,156,211,0.85)</code>)</td><td>the blue world</td></tr><tr><td><strong>Mars rust</strong></td><td><code>#c1440e</code> (<code>rgba(193,68,14,0.85)</code>)</td><td>the red world / warm secondary</td></tr><tr><td><strong>Structure whites</strong></td><td><code>rgba(255,255,255,α)</code> at α = <code>0.1 / 0.18–0.22 / 0.35–0.4 / 0.55</code></td><td>orbit rings &amp; geometry, faint→bright tiers</td></tr><tr><td><strong>Stars</strong></td><td>white <code>0.45–0.5</code> (bright), <code>0.22–0.25</code> (dim), r ≈ 0.6–1.2</td><td>scattered sparse, never busy</td></tr><tr><td><strong>Caption ink</strong></td><td><code>rgba(255,255,255,0.45)</code></td><td>the whisper-caption</td></tr></tbody></table><p><strong>Discipline:</strong> exactly <strong>one</strong> cyan accent element per cover. Everything else is white-on-navy at varying opacity, plus the warm sun and at most two colored worlds (blue, rust). More color = dilution.</p><hr><h2 id="_3-composition" tabindex="-1">3. Composition <a class="header-anchor" href="#_3-composition" aria-label="Permalink to &quot;3. Composition&quot;">​</a></h2><ul><li><strong>Canvas:</strong> covers <code>viewBox=&quot;0 0 600 260&quot;</code> (≈ 2.3∶1). Landing hero: wider, see §6.</li><li><strong>One focal system, off-center.</strong> scales-time anchors the sun-system at left (cx≈80); transfers spans a single arc across the middle. Negative space is the point — let the field breathe. Roughly 50–65% of the canvas stays near-empty.</li><li><strong>Orbit rings:</strong> concentric ellipses, opacity tiered faint→bright as they near the focus. One ring (or one arc) is promoted to cyan <code>#4ecdc4</code>; the rest are white tiers.</li><li><strong>Glow:</strong> the sun and any bright node carry a soft radial glow. Worlds get a faint 1-ring halo (e.g. Earth <code>r=8</code> body + <code>r=14</code> <code>0.3</code>-opacity ring).</li><li><strong>Stars:</strong> 8–12 max, scattered top + bottom margins, mixed bright/dim. Sparse. Never a starfield.</li><li><strong>No hard edges, no boxes, no charts, no icons, no arrows-with-arrowheads-as-UI.</strong> Curves and dots only.</li></ul><hr><h2 id="_4-typography-—-the-whisper-caption" tabindex="-1">4. Typography — the whisper-caption <a class="header-anchor" href="#_4-typography-—-the-whisper-caption" aria-label="Permalink to &quot;4. Typography — the whisper-caption&quot;">​</a></h2><ul><li><strong>Font:</strong> <code>&#39;Crimson Pro&#39;, serif</code>, <strong>italic</strong>, ~13px on the 600×260 canvas (scale for hero).</li><li><strong>Ink:</strong> <code>rgba(255,255,255,0.45)</code> — quiet, never competing with the art.</li><li><strong>Placement:</strong> a corner (porkchop uses all four sparingly; scales-time uses bottom-right <code>text-anchor=&quot;end&quot;</code>).</li><li><strong>Voice — lowercase, lyric, ≤4 words per line.</strong> It names a <em>feeling</em>, not a fact: <ul><li>scales-time → <em>&quot;vast and quiet&quot;</em></li><li>porkchop → <em>&quot;expensive / cheap&quot;</em> + <em>&quot;a map of / when to leave&quot;</em></li><li>Write new ones in this register. NEVER monospace, NEVER UPPERCASE, NEVER a label like <code>LAUNCH</code> or <code>BONE MUSC CM</code>.</li></ul></li></ul><hr><h2 id="_5-per-chapter-motif-cues-celestial-translations" tabindex="-1">5. Per-chapter motif cues (celestial translations) <a class="header-anchor" href="#_5-per-chapter-motif-cues-celestial-translations" aria-label="Permalink to &quot;5. Per-chapter motif cues (celestial translations)&quot;">​</a></h2><p>For the 6 diluted covers, re-express the subject celestially:</p><table tabindex="0"><thead><tr><th>Chapter</th><th>Diluted version (avoid)</th><th>Celestial translation (target)</th></tr></thead><tbody><tr><td>history</td><td>timeline + year ticks</td><td>a single long arc sweeping across deep field, faint earlier orbits ghosting behind — <em>&quot;how far we&#39;ve come&quot;</em></td></tr><tr><td>propulsion</td><td>rocket icon on a line</td><td>one bright cyan thrust-arc leaving a glowing node, exhaust as a fading trail — <em>&quot;the long push&quot;</em></td></tr><tr><td>space-stations</td><td>wireframe truss boxes</td><td>a single bright node on a low ring around a blue world, faint horizon curve — <em>&quot;a home in orbit&quot;</em></td></tr><tr><td>life-in-space</td><td>astronaut + bar charts</td><td>a lone soft figure-glow against vast field, one tether-line to a bright node — <em>&quot;fragile and far&quot;</em></td></tr><tr><td>observation</td><td>telescope box + spectrum bar</td><td>a faint dotted sight-line from a near node to a distant glowing galaxy-spiral — <em>&quot;listening to light&quot;</em></td></tr><tr><td>mission-phases</td><td>LAUNCH→LEO→CRUISE flowchart</td><td>one continuous arc rising from a blue world, cresting, settling at a rust world — phases as glow-nodes, not labels — <em>&quot;the whole journey, one line&quot;</em></td></tr></tbody></table><hr><h2 id="_6-the-science-landing-hero-option-1" tabindex="-1">6. The /science landing hero (Option 1) <a class="header-anchor" href="#_6-the-science-landing-hero-option-1" aria-label="Permalink to &quot;6. The /science landing hero (Option 1)&quot;">​</a></h2><p>The landing page currently has <strong>no hero</strong>. Add one in this style, but <em>grander</em> — it&#39;s the overture to the whole encyclopedia, so it may combine motifs (a sun-system + a transfer arc + distant galaxy) rather than a single chapter&#39;s.</p><ul><li><strong>Aspect:</strong> wide cinematic banner — target <strong>~16∶6 to 21∶9</strong> (e.g. 1600×600 or 1920×640), responsive-cropped. Confirm exact bleed against the landing layout before final.</li><li><strong>Composition:</strong> the full poetic vocabulary at once — off-center glowing sun, tiered orbit rings, one cyan focal arc, a scatter of worlds receding, sparse stars, deep <code>#04040c</code> field.</li><li><strong>Caption:</strong> one whisper-line, landing-scale, lower corner. Candidate voice: <em>&quot;everything moves&quot;</em> / <em>&quot;the sky, explained&quot;</em> / <em>&quot;vast, and knowable&quot;</em> (pick at gen time).</li><li><strong>Format:</strong> WebP. (Covers are currently SVG; the colophon manifest auto-scans <code>*.svg</code> — going raster touches <code>science/[tab]</code> cover markup + <code>build-original-work.mjs</code>. The landing hero is a <em>new</em> asset so it has no such constraint — render it freely.)</li><li><strong>LOCKED 2026-06-23:</strong> <code>landing-hero-2</code> — flat overture (sun + tilted rings + cyan arc + faint galaxy), generated via the §7 locked-reference method. Vast right-side void for <code>h1</code> + lede. Staged at <code>/tmp/sci-render/LOCKED/_science-landing-hero.png</code>. New asset → wire straight into <code>src/routes/science/+page.svelte</code> <code>.hero</code> (no manifest conflict).</li></ul><hr><h2 id="_7-higgsfield-generation-recipe-—-validated-method-2026-06-23" tabindex="-1">7. Higgsfield generation recipe — VALIDATED METHOD (2026-06-23) <a class="header-anchor" href="#_7-higgsfield-generation-recipe-—-validated-method-2026-06-23" aria-label="Permalink to &quot;7. Higgsfield generation recipe — VALIDATED METHOD (2026-06-23)&quot;">​</a></h2><p><strong>Do NOT elevate the style.</strong> A detour tried &quot;premium / luminous / atmospheric depth&quot; renders (nano_banana, nebula haze, 3D-ish sun) and a hand-authored SVG uplift — both were rejected as <em>worse than the originals</em>. The loved flat covers are good <strong>as they are</strong>. The job is only to bring the diluted covers up to the <em>same</em> flat language — faithful family-matching, not elevation.</p><p><strong>The method that worked — locked multi-reference conditioning:</strong></p><ol><li><strong>Lock 3 loved covers as a combined style reference.</strong> Render <code>_cover-scales-time</code>, <code>_cover-orbits</code>, <code>_cover-transfers</code> at ~1200px wide on a <code>#04040c</code> field; <code>media_upload</code> + <code>media_confirm</code> each; pass all three as <code>medias:[{role:&#39;image&#39;}]</code>. Multiple refs average the <em>style</em> so the model doesn&#39;t clone a single <em>composition</em>.</li><li><strong>Model:</strong> <code>nano_banana_2</code> (Higgsfield routes it to <code>nano_banana_flash</code> — fine). It honors image references hard, which is what locks the flat look. Recraft <code>vector</code> mode outputs real SVG but couldn&#39;t take a reference image → drifted; not used for the series.</li><li><strong>Aspect <code>21:9</code>, resolution <code>2k</code>, count 2–3</strong> per subject. ~1 credit each. Output is <strong>raster PNG</strong> (3168×1344 ≈ the covers&#39; 2.31∶1) — mixed-format vs the SVG originals, but visually identical family.</li><li><strong>Prompt template</strong> (the load-bearing part is the style-lock preamble + per-subject motif): <blockquote><p>A chapter cover illustration in the EXACT same flat 2D minimalist vector style as the reference images — same deep near-black navy field (#04040c), same thin delicate white elliptical orbit lines, same single soft cyan-teal (#4ecdc4) accent, same sparse faint stars, same restraint and vast negative space. Strictly FLAT 2D, NO 3D, NO realistic shading, NO photographic rendering, NO nebula, NO texture. <strong>Subject for THIS cover ([chapter] — [§5 celestial translation]): [bespoke composition].</strong> No text, no labels, no numbers, no icons, no rockets, no spacecraft hardware, no human figures, no boxes, no charts, no wireframes.</p></blockquote></li></ol><p><strong>Negative / must-not:</strong> rockets, spacecraft hardware, wireframes, boxes, bar charts, timelines, monospace text, UPPERCASE labels, arrows, busy starfields, photoreal 3D, nebula haze, lens flare, logos. <strong>Caption is overlaid in-app, never generated</strong> — image models garble text.</p><p><strong>Per-subject note — <code>life-in-space</code></strong> broke the family&#39;s cyan-only rule on purpose: its concept is <em>&quot;we are stardust&quot;</em> — an amber star shedding glowing dust that coalesces into a green+blue cluster around a <strong>carbon hexagon</strong>. Green is an intentional, meaningful palette extension for <em>life</em>; warmth/green = life is the whole point. When a subject has a real reason to bend the palette, bend it — but only for a reason this strong.</p><p><strong>Acceptance checklist (every generation):</strong></p><ul><li>[ ] Field reads <code>#04040c</code>, flat 2D, no 3D/nebula/photoreal</li><li>[ ] Single accent (cyan — or amber/green only with a §-strong reason)</li><li>[ ] Negative space ≥ ~50%</li><li>[ ] Zero text/icons/boxes/labels baked in</li><li>[ ] Sits beside <code>scales-time</code> / <code>orbits</code> / <code>transfers</code> without looking foreign</li><li>[ ] Reads as its subject (the diluted original&#39;s meaning, re-told celestially)</li></ul><p><strong>Locked set (6 diluted covers re-done, 2026-06-23):</strong> history, mission-phases, propulsion, space-stations, observation, life-in-space. Staged as raster at <code>/tmp/sci-render/LOCKED/</code> pending the format + wiring decision (§8).</p><hr><h2 id="_8-wiring-format-—-open-decision" tabindex="-1">8. Wiring &amp; format — OPEN DECISION <a class="header-anchor" href="#_8-wiring-format-—-open-decision" aria-label="Permalink to &quot;8. Wiring &amp; format — OPEN DECISION&quot;">​</a></h2><p>The 6 re-done covers are <strong>raster PNG (21:9, 3168×1344)</strong>; the live covers are <strong>SVG</strong> (<code>static/diagrams/science/_cover-{tab}.svg</code>, 600×260). Installing the new set touches:</p><ul><li><strong>Cover markup</strong> — <code>src/routes/science/[tab]/+page.svelte</code> hard-codes <code>/diagrams/science/_cover-{tab}.svg</code>. The 6 raster covers need either <code>.webp</code> with an extension-aware path, or per-tab format handling.</li><li><strong>Colophon manifest</strong> — <code>scripts/build-original-work.mjs</code> auto-scans <code>*.svg</code> in <code>static/diagrams/science/</code>. Raster covers won&#39;t be picked up unless the scan + the colophon &quot;Science Diagrams&quot; grid (<code>src/routes/colophon/+page.svelte</code>) learn about non-SVG covers.</li><li><strong>Optimization</strong> — 2K PNG is heavy; convert to <code>.webp</code> (and a mobile-tier variant) before ship.</li><li><strong>Captions</strong> — overlay the serif whisper-caption in-app (not on the raster), per §4/§6.</li></ul><p>Two clean resolutions: <strong>(a)</strong> keep raster for the 6 new + SVG for the 5 loved (mixed, smallest change), or <strong>(b)</strong> trace the raster to SVG to keep the whole set one format (more work, uniform pipeline). Decision pending; do not wire in until chosen and per-image approval is on record.</p><hr><p><em>Single source of truth for science cover art. Update the version line + date on any change. Linked from the asset pipeline; pair with <code>docs/anatomy-art-runbook.md</code> for the broader art system.</em></p>',46)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
